// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(amount == 10);
        vm.deal(caller, amount);

        uint256 potBefore = c.pot();

        vm.prank(caller);
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        uint256 potAfter = c.pot();

        assertTrue(potBefore != potAfter);
    }
}

